def sumAmicableUpTo(n):
    limit = 4 * n + 10
    s = [0] * (limit + 1)
    for d in range(1, limit // 2 + 1):
        for m in range(2 * d, limit + 1, d):
            s[m] += d
    total = 0
    for a in range(1, n + 1):
        b = s[a]
        if b != a and 1 <= b <= limit and s[b] == a:
            total += a
    return total
